# apply_pit_and_run.py — adds pit-crew rolling features from lap-time inference
# and compares matchup LL vs previous best (0.6176).
import base64, sys, pathlib

FILES = {
    'src/features/pit.py': '',
    'src/features/build_features.py': '',
    'src/models/gbm_ranker.py': '',
}


def main():
    for target, b64 in FILES.items():
        p = pathlib.Path(target)
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_bytes(base64.b64decode(b64))
        print(f"wrote {target}")

    import pandas as pd
    from src.eval.backtest_gbm_walkforward import backtest_gbm_walkforward, summarize_wf

    TIGHT_REG = {"num_leaves": 31, "min_data_in_leaf": 25, "lambda_l2": 2.0}
    ALPHA = 0.85

    races = pd.read_parquet("data/processed/races.parquet").sort_values("date").reset_index(drop=True)
    entries = pd.read_parquet("data/processed/entries.parquet")
    sessions = pd.read_parquet("data/processed/sessions.parquet")
    loopstats = pd.read_parquet("data/processed/loopstats.parquet")
    laptimes = pd.read_parquet("data/processed/laptimes.parquet")

    print(f"\n=== walk-forward with pit features (ensemble=3, tight-reg) ===")
    out = backtest_gbm_walkforward(
        races, entries, sessions, loopstats, laptimes=laptimes,
        initial_train_races=36, retrain_every_n=10,
        calib_window=25, recalibrate_every_n=10,
        ensemble_alpha=ALPHA, n_samples=3000,
        gbm_fit_kwargs=TIGHT_REG,
        n_ensemble=3,
    )
    by_type = summarize_wf(out["metrics"])
    print(by_type.round(4).to_string())

    row = by_type.loc["ALL"]
    print(f"\nmatchup_ll={row['matchup_logloss']:.4f}  winner_ll={row['winner_logloss']:.4f}  "
          f"spearman={row['spearman_rho']:.4f}  top5={row['top5_accuracy']:.4f}")

    # Feature importance for the new pit features.
    try:
        booster = out["model"].booster
        imp = pd.DataFrame({
            "feature": booster.feature_name(),
            "gain": booster.feature_importance(importance_type="gain"),
        }).sort_values("gain", ascending=False).reset_index(drop=True)
        for f in ["pit_gain_5", "pit_gain_10", "pit_time_delta_10"]:
            row = imp[imp["feature"] == f]
            if len(row):
                rank = int(imp.index[imp["feature"] == f][0]) + 1
                print(f"  {f}: gain={row['gain'].iloc[0]:.1f}, rank #{rank}")
    except Exception as e:
        print(f"(feat importance skipped: {e})")

if __name__ == "__main__":
    main()
